#!/usr/bin/env python3
"""Render the planning matrix from its canonical JSON requirement records."""
from pathlib import Path
from collections import Counter
import json
ROOT=Path(__file__).resolve().parents[2]
source=ROOT/'docs/jbpa-management-requirements.json'
m=json.loads(source.read_text());rows=m['requirements'];ids=[r['id'] for r in rows]
if len(ids)!=len(set(ids)):raise ValueError('Duplicate requirement ID')
def cell(s):return str(s).replace('|','\\|').replace('\n',' ')
scopes={'BASELINE':'Baseline','OPTIONAL_DEPLOYMENT_PROFILE':'Optional deployment','OPTIONAL_INTEGRATION':'Optional integration','CONDITIONAL_DEPLOYMENT':'Conditional deployment','REQUIRES_QUALIFICATION':'Qualification required','SCOPED_QUALIFICATION':'Scoped qualification','FUTURE_QUALIFIED_PROFILE':'Future profile','UPG-001_DEFERRED':'Deferred UPG-001','UPG-002_CANDIDATE':'Candidate UPG-002','SKILL_SECURITY_FINAL_DEFERRED':'Deferred final skill security phase'}
statuses={'PROPOSED':'Proposed','EXISTING_QA_CALLER_PLUS_NEW_WIZARD':'QA caller exists; wizard proposed','EXISTING_SCOPED_QA_EVIDENCE':'Scoped QA evidence','DEFERRED_UNTIL_BASELINE_VALIDATED':'Deferred until baseline validated','DEFERRED_COMPATIBILITY_CANDIDATE':'Compatibility not verified','DOCUMENT_STYLE_ACCEPTED':'Document style accepted','RECORDED':'Recorded','LOCAL_CODE_TESTED_LIVE_QUALIFICATION_PENDING':'Local code tested; live qualification pending','DEFERRED_UNTIL_EXPLICIT_IMPLEMENTATION_REQUEST':'Deferred; explicit implementation request required'}
out=['# JBPA Management Requirements Matrix','',f'Updated {m["updatedAt"]}. {len(rows)} requirements across {len(set(r["area"] for r in rows))} areas.','',m['purpose'],'','The [canonical JSON](jbpa-management-requirements.json) owns the requirement IDs, scope, decision status, implementation status, contract and acceptance criteria. This readable matrix is generated from it. Update the JSON first, then run `python scripts/management/render-requirements-matrix.py`.','', '## MCP driven setup and minimal bootstrap','', '| Entry point | Customer interaction | Bootstrap requirement |','| --- | --- | --- |','| Minimal management bootstrap | Deploy the management service and required authenticated Jitterbit integration | Must precede MCP onboarding |','| Jitterbit MCP guided onboarding | Product-owned Markdown guide plus structured options, file IDs, configuration, validation and execution tools | Primary customer onboarding interface; no local AI shell access |','| Jitterbit file upload route | Capable client/uploader or private upload page sends bytes through APIM/Studio to management storage | AI receives safe file references, not private-key contents |','', 'The backend owns setup state and validates every field/mapping. Markdown tells the AI what to ask; it is neither executable configuration nor an authorization mechanism. The previously proposed AI-assisted terminal installer is superseded as the primary customer flow.','', '## Multiple host selection example','', 'Illustrative selections only; these are not actual customer hosts or credential files. The AI uses MCP options to ask for the host count, discover staged/uploaded files, then repeat host-specific questions. It can offer an explicit apply-to-all default with overrides.','', '| Host | Selected SSH file ID | Selected registration profile | Setup state |','| --- | --- | --- | --- |','| Host 1 | key-01 | group-a-profile | Awaiting validation |','| Host 2 | key-03 | group-a-profile | Awaiting validation |','| Host 3 | key-02 | group-b-profile | Awaiting validation |','| Host 4 | key-04 | group-b-profile | Awaiting validation |','', 'If four private keys are staged, the setup options API shows all four usable candidates by safe name/ID. Ask which applies to each host; do not infer the answer from names or host order. Apply the same typed selection to certificates and other optional configuration. Reuse across hosts is an explicit choice.','', '## Changing the group being managed','', 'Selecting another authorized group/profile changes discovery and future selections. A submitted job keeps its recorded target, group and profile revision. An installed PA is not moved, re-registered or reinstalled by changing the active context. Moving an installed PA is a separately qualified and authorized lifecycle operation.','', '## Requirement matrix','', 'Baseline rows are first-release requirements. Qualification-required options must remain unavailable until their implementation and evidence exist. Observability is deferred until baseline validation. Existing QA evidence is scoped and does not certify the proposed management product.','']
out += ['## Deferred skill security phase', '', 'The immediate security scope is the JBPA skill through Codex/Claude, not an MCP redesign. SEC-SKL-001 through SEC-SKL-014 are agreed design only: implement last among selected functional phases and only on an explicit user request. Production monitoring is read-only; install, upgrade, uninstall and deregistration require a separate approval workflow. No skill/runtime controls are changed by this matrix. Production access remains gated on implementation and qualification. See the [skill security architecture](skill-security-architecture.md).', '']
areas=list(dict.fromkeys(r['area'] for r in rows))
for area in areas:
 out+=['### '+area,'','| ID | Requirement and scope | Required behavior | Acceptance and current delivery |','| --- | --- | --- | --- |']
 for r in rows:
  if r['area']!=area:continue
  requirement=f'**{r["requirement"]}**<br>{scopes.get(r["scope"],r["scope"])}'
  acceptance=r['acceptance']+'<br>**Delivery:** '+statuses.get(r['implementationStatus'],r['implementationStatus'])
  out.append('| '+' | '.join(cell(v) for v in [r['id'],requirement,r['contract'],acceptance])+' |')
 out.append('')
out+=['## Decision changes','']
for change in m.get('decisionChanges',[]):out.extend(['- '+change['date']+': '+change['decision']+' Superseded: '+change['superseded'],''])
out+=['## Stored relationships','', '| Record | Required fields |','| --- | --- |']
for key,label in [('hostFields','Target'),('accessProfileFields','Access profile'),('registrationProfileFields','Registration profile'),('fileCandidateFields','Discovered file'),('setupStateFields','Setup session')]:out.append('| '+label+' | '+', '.join(m['relationships'][key])+' |')
out+=['', 'These are proposed product records, not changes already made to the current remote-inventory schema. Secret fields use references; actual private keys and tokens do not belong in the matrix or setup-status payload.','', '## Source and revision references','', '- [Product specification](jbpa-management-product.md)','- [Deferred skill security architecture](skill-security-architecture.md)','- [Baseline and upgrade roadmap](jbpa-management-roadmap.json)','- [Existing remote inventory schema](../config/schemas/remote-inventory.schema.json)','- [Existing customer credentials example](../config/examples/customer-credentials.example.json)','- [Production readiness and scoped evidence](production-readiness.md)','- [HLA and revision boundary](hla/README.md)','', 'The PDF v8 predates these onboarding/group refinements. The current matrix and product specification retain the decisions until the PDF is revised.','']
(ROOT/'docs/jbpa-management-requirements-matrix.md').write_text('\n'.join(out))
print(f'Rendered {len(rows)} unique requirements in {len(areas)} sections.')
